after.content:
$ErrorActionPreference = 'Stop'
$root = Split-Path -Parent $PSScriptRoot
Push-Location $root
try {
  & node .\scripts\verify-module-boundaries.mjs
  if ($LASTEXITCODE -ne 0) { throw "module boundary gate failed: $LASTEXITCODE" }
  & node .\scripts\verify-api-baseline.mjs
  if ($LASTEXITCODE -ne 0) { throw "API baseline gate failed: $LASTEXITCODE" }
  & .\gradlew.bat :ji-telemetry-api:test :ji-telemetry-otel:test :ji-artifact-api:test :ji-artifact-filesystem:test :ji-session-export:test --offline --rerun-tasks
  if ($LASTEXITCODE -ne 0) { throw "Stage 2 observability/artifact tests failed: $LASTEXITCODE" }
  & node .\scripts\verify-generated.mjs
  if ($LASTEXITCODE -ne 0) { throw "generated contract gate failed: $LASTEXITCODE" }
} finally {
  Pop-Location
}
